1	import { Agent } from "@mastra/core/agent";
2	import { memory } from "../memory";
3	import { wrapMastra } from "neatlogs/mastra";
4	import { ASSISTANT_INSTRUCTIONS } from "../prompts";
5	import { marketResearcher } from "./market-researcher";
6	import { cfoAgent } from "./cfo";
7	import { githubReaderAgent } from "./github";
8	import { neatlogsReaderAgent } from "./neatlogs";
9	
10	export const assistant = wrapMastra(new Agent({
11	  id: "assistant",
12	  name: "Assistant",
13	  description: "Primary assistant that handles conversations and coordinates specialist agents.",
14	  instructions: ASSISTANT_INSTRUCTIONS,
15	  model: "deepseek/deepseek-flash",
16	  memory,
17	  // Delegation gets the read-only GitHub and Neatlogs agents: the assistant's chat cannot
18	  // show an approval prompt for a sub-agent's write. Writes happen in each agent's own chat.
19	  // The keys match the registered agents ("githubAgent", "neatlogsAgent") so the prompt and the web UI's "agent-<key>" labels still match.
20	  agents: { marketResearcher, cfoAgent, githubAgent: githubReaderAgent, neatlogsAgent: neatlogsReaderAgent },
21	  defaultOptions: {
22	    maxSteps: 6,
23	    delegation: {
24	      onDelegationStart: () => ({ modifiedMaxSteps: 12 }),
25	    },
26	  },
27	}));
28

1	import { MCPClient, type RequireToolApprovalContext } from "@mastra/mcp";
2	
3	/**
4	 * Deny by default: a tool skips approval only when GitHub's MCP server annotates it with
5	 * `readOnlyHint: true` (the server sets it explicitly on every read tool). Write tools, and any
6	 * tool without that annotation, need human approval.
7	 */
8	export function githubToolNeedsApproval({
9	  annotations,
10	}: Pick<RequireToolApprovalContext, "annotations">): boolean {
11	  return annotations?.readOnlyHint !== true;
12	}
13	
14	// GitHub's official remote MCP server: https://github.com/github/github-mcp-server
15	// Auth: a personal access token in GITHUB_PAT. Writes are enabled, but every non-read tool
16	// call suspends for human approval (see githubToolNeedsApproval). The toolset header limits
17	// the server to repos, issues, PRs and Actions so the model sees a small tool surface.
18	export const githubMcp = new MCPClient({
19	  id: "github",
20	  servers: {
21	    github: {
22	      url: new URL("https://api.githubcopilot.com/mcp/"),
23	      requestInit: {
24	        headers: {
25	          Authorization: `Bearer ${process.env.GITHUB_PAT}`,
26	          "X-MCP-Toolsets": "context,repos,issues,pull_requests,actions",
27	        },
28	      },
29	      // Refuse to follow redirects/requests to any other host with the token attached.
30	      allowedHosts: ["api.githubcopilot.com"],
31	      requireToolApproval: githubToolNeedsApproval,
32	    },
33	  },
34	});
35	
36	type GithubTools = Awaited<ReturnType<typeof githubMcp.listTools>>;
37	let cached: GithubTools | undefined;
38	
39	/**
40	 * Resolves the GitHub MCP tools lazily (the agent calls this per request). Degrades to no tools
41	 * (logging a warning) when GITHUB_PAT is missing or the connection fails, so the server still
42	 * boots without a token. Only a successful fetch is cached, so a later retry can recover.
43	 */
44	export async function getGithubTools(): Promise<GithubTools> {
45	  if (cached) return cached;
46	  if (!process.env.GITHUB_PAT) {
47	    console.warn("[github] GITHUB_PAT is not set; the GitHub agent has no tools");
48	    return {};
49	  }
50	  try {
51	    // listTools() reports a failed server as an empty result instead of throwing; don't cache that.
52	    const tools = await githubMcp.listTools();
53	    if (Object.keys(tools).length > 0) cached = tools;
54	    return tools;
55	  } catch (error) {
56	    console.warn("[github] could not load GitHub MCP tools:", error instanceof Error ? error.message : error);
57	    return {};
58	  }
59	}
60	
61	const TOOL_KEY_PREFIX = "github_"; // listTools() namespaces tools as `<server>_<tool>`.
62	
63	/**
64	 * Only the tools that never need approval, for callers that cannot show an approval prompt
65	 * (delegation from the assistant). Same predicate as the
66	 * approval gate, so a tool is either listed here or would have suspended for approval.
67	 */
68	export async function getGithubReadTools(): Promise<GithubTools> {
69	  const tools = await getGithubTools();
70	  return Object.fromEntries(
71	    Object.entries(tools).filter(([key, tool]) => {
72	      if (!key.startsWith(TOOL_KEY_PREFIX)) return false;
73	      const annotations = (tool as { mcp?: { annotations?: RequireToolApprovalContext["annotations"] } }).mcp?.annotations;
74	      return !githubToolNeedsApproval({ annotations });
75	    }),
76	  );
77	}
78

1	import { MCPClient, type RequireToolApprovalContext } from "@mastra/mcp";
2	
3	/**
4	 * Neatlogs' MCP tools carry no annotations (no readOnlyHint), so approval is decided by name:
5	 * only these known read tools skip approval. Every other tool (triage/detection writes, and any
6	 * tool the server adds later) needs human approval. Deny by default.
7	 */
8	export const NEATLOGS_READ_TOOLS: ReadonlySet<string> = new Set([
9	  "ping",
10	  "whoami",
11	  "search_traces",
12	  "get_trace_context",
13	  "get_trace_evaluations",
14	  "get_project_analytics",
15	  "list_detections",
16	  "get_detection_trend",
17	  "list_detection_groups",
18	  "get_detection_capabilities",
19	  "get_detection_status",
20	  "triage_list",
21	  "triage_get",
22	  "triage_get_investigation",
23	  "triage_list_steps",
24	  "triage_list_versions",
25	  "triage_get_version",
26	]);
27	
28	/** Never exposed to the agent: it ingests traces rather than reading or triaging them. */
29	const NEATLOGS_EXCLUDED_TOOLS: ReadonlySet<string> = new Set(["log_trace"]);
30	
31	export function neatlogsToolNeedsApproval({ toolName }: Pick<RequireToolApprovalContext, "toolName">): boolean {
32	  return !NEATLOGS_READ_TOOLS.has(toolName);
33	}
34	
35	// Neatlogs' hosted MCP server, authenticated with the same project key the tracing SDK uses.
36	export const neatlogsMcp = new MCPClient({
37	  id: "neatlogs",
38	  servers: {
39	    neatlogs: {
40	      url: new URL("https://ingest.neatlogs.com/mcp"),
41	      requestInit: {
42	        headers: { Authorization: `Bearer ${process.env.NEATLOGS_API_KEY}` },
43	      },
44	      // Refuse to follow redirects/requests to any other host with the key attached.
45	      allowedHosts: ["ingest.neatlogs.com"],
46	      requireToolApproval: neatlogsToolNeedsApproval,
47	    },
48	  },
49	});
50	
51	type NeatlogsTools = Awaited<ReturnType<typeof neatlogsMcp.listTools>>;
52	let cached: NeatlogsTools | undefined;
53	
54	const TOOL_KEY_PREFIX = "neatlogs_"; // listTools() namespaces tools as `<server>_<tool>`.
55	
56	function toolName(key: string): string | undefined {
57	  return key.startsWith(TOOL_KEY_PREFIX) ? key.slice(TOOL_KEY_PREFIX.length) : undefined;
58	}
59	
60	/**
61	 * Resolves the Neatlogs MCP tools lazily (the agent calls this per request), minus excluded ones.
62	 * Degrades to no tools (logging a warning) when NEATLOGS_API_KEY is missing or the connection
63	 * fails, so the server still boots. Only a successful, non-empty fetch is cached.
64	 */
65	export async function getNeatlogsTools(): Promise<NeatlogsTools> {
66	  if (cached) return cached;
67	  if (!process.env.NEATLOGS_API_KEY) {
68	    console.warn("[neatlogs] NEATLOGS_API_KEY is not set; the Neatlogs agent has no tools");
69	    return {};
70	  }
71	  try {
72	    // listTools() reports a failed server as an empty result instead of throwing; don't cache that.
73	    const all = await neatlogsMcp.listTools();
74	    const tools = Object.fromEntries(
75	      Object.entries(all).filter(([key]) => {
76	        const name = toolName(key);
77	        return name !== undefined && !NEATLOGS_EXCLUDED_TOOLS.has(name);
78	      }),
79	    ) as NeatlogsTools;
80	    if (Object.keys(tools).length > 0) cached = tools;
81	    return tools;
82	  } catch (error) {
83	    console.warn("[neatlogs] could not load Neatlogs MCP tools:", error instanceof Error ? error.message : error);
84	    return {};
85	  }
86	}
87	
88	/**
89	 * Only the read allowlist, for callers that cannot show an approval prompt (delegation from the
90	 * assistant). Same predicate as the approval gate.
91	 */
92	export async function getNeatlogsReadTools(): Promise<NeatlogsTools> {
93	  const tools = await getNeatlogsTools();
94	  return Object.fromEntries(
95	    Object.entries(tools).filter(([key]) => {
96	      const name = toolName(key);
97	      return name !== undefined && !neatlogsToolNeedsApproval({ toolName: name });
98	    }),
99	  ) as NeatlogsTools;
100	}
