1	import { isToolUIPart, type UIMessage } from "ai";
2	
3	/** A stored message, as returned by Mastra Memory recall (MastraDBMessage), narrowed to what is read here. */
4	type StoredMessage = { role: string; content: unknown };
5	
6	/**
7	 * Approval ids ("<runId>::<toolCallId>", the id the AI SDK stream carries) still awaiting a
8	 * decision in a stored thread. Mastra records each suspended approval under the assistant
9	 * message's `content.metadata.pendingToolApprovals` and removes it once the call is resumed.
10	 */
11	export function pendingApprovalIds(messages: readonly StoredMessage[]): Set<string> {
12	  const ids = new Set<string>();
13	  for (const message of messages) {
14	    if (message.role !== "assistant") continue;
15	    const metadata = (message.content as { metadata?: { pendingToolApprovals?: unknown } } | null)?.metadata;
16	    const pending = metadata?.pendingToolApprovals;
17	    if (!pending || typeof pending !== "object") continue;
18	    for (const entry of Object.values(pending)) {
19	      const { runId, toolCallId } = (entry ?? {}) as { runId?: unknown; toolCallId?: unknown };
20	      if (typeof runId === "string" && runId && typeof toolCallId === "string" && toolCallId) {
21	        ids.add(`${runId}::${toolCallId}`);
22	      }
23	    }
24	  }
25	  return ids;
26	}
27	
28	/**
29	 * For dropping approvals the user moved on from: the stored assistant messages that still hold
30	 * pending approvals, reduced to { id, content } with those approvals removed, and the suspended
31	 * agent runs they belonged to. Storage merges metadata keys on update, so the key is set to
32	 * undefined (left out when serialized) rather than deleted.
33	 */
34	export function withoutPendingApprovals<M extends StoredMessage & { id: string; content: { metadata?: Record<string, unknown> } }>(
35	  messages: readonly M[],
36	): { messages: Pick<M, "id" | "content">[]; runIds: Set<string> } {
37	  const cleared: Pick<M, "id" | "content">[] = [];
38	  const runIds = new Set<string>();
39	  for (const message of messages) {
40	    const metadata = message.content.metadata;
41	    if (message.role !== "assistant" || !metadata?.pendingToolApprovals) continue;
42	    for (const id of pendingApprovalIds([message])) runIds.add(id.slice(0, id.lastIndexOf("::")));
43	    cleared.push({ id: message.id, content: { ...message.content, metadata: { ...metadata, pendingToolApprovals: undefined } } });
44	  }
45	  return { messages: cleared, runIds };
46	}
47	
48	/**
49	 * Rebuilds a client's approval response as the assistant message handleChatStream resumes from
50	 * (it reads only "approval-responded" tool parts). Keeps only decisions for approvals pending in
51	 * the caller's own thread, so a client cannot resume another user's run, and copies only the
52	 * fields Mastra reads (no client reason text). Undefined when nothing valid is left.
53	 */
54	export function approvalResumeMessage(message: UIMessage, pending: ReadonlySet<string>): UIMessage | undefined {
55	  const parts: UIMessage["parts"] = [];
56	  for (const part of message.parts ?? []) {
57	    if (!isToolUIPart(part) || part.state !== "approval-responded") continue;
58	    const { id, approved } = part.approval ?? {};
59	    if (typeof id !== "string" || typeof approved !== "boolean" || !pending.has(id)) continue;
60	    if (!id.endsWith(`::${part.toolCallId}`)) continue;
61	    parts.push({ ...part, approval: { id, approved }, state: "approval-responded" } as UIMessage["parts"][number]);
62	  }
63	  return parts.length > 0 ? { id: message.id, role: "assistant", parts } : undefined;
64	}
