1	import type http from "node:http";
2	import { handleChatStream } from "@mastra/ai-sdk";
3	import { toAISdkMessages } from "@mastra/ai-sdk/ui";
4	import { createUIMessageStreamResponse, type UIMessage } from "ai";
5	import { canUseAgent } from "./auth/access";
6	import { approvalResumeMessage, pendingApprovalIds, withoutPendingApprovals } from "./chat-approvals";
7	import type { SessionUser } from "./auth/session";
8	import { mastra } from "./mastra";
9	
10	const MAX_BODY_BYTES = 1024 * 1024;
11	
12	export type AgentSummary = { key: string; id: string; name: string; description: string };
13	
14	/** Without a user, returns every agent; with one, only the agents that user may use. */
15	export function listAgents(user?: SessionUser): AgentSummary[] {
16	  return Object.entries(mastra.listAgents())
17	    .map(([key, agent]) => ({
18	      key,
19	      id: agent.id,
20	      name: agent.name,
21	      description: agent.getDescription(),
22	    }))
23	    .filter((agent) => !user || canUseAgent(user, agent.id));
24	}
25	
26	/** Accepts either the Mastra registry key ("cfoAgent") or the agent id ("cfo"). */
27	function resolveAgentId(keyOrId: string): string | undefined {
28	  return listAgents().find((agent) => agent.key === keyOrId || agent.id === keyOrId)?.id;
29	}
30	
31	/** One persisted chat per user per agent. */
32	export function chatThreadId(userId: string, agentId: string): string {
33	  return `${userId}:${agentId}`;
34	}
35	
36	/** POST /api/chat/:agentId — streams an AI SDK v7 UI message stream (SSE). */
37	export async function handleChat(
38	  agentKeyOrId: string,
39	  req: http.IncomingMessage,
40	  res: http.ServerResponse,
41	  user: SessionUser,
42	): Promise<void> {
43	  if (req.method !== "POST") {
44	    res.writeHead(405, { allow: "POST" }).end();
45	    return;
46	  }
47	  const agentId = resolveAgentId(agentKeyOrId);
48	  if (!agentId) {
49	    sendJson(res, 404, { error: `Unknown agent: ${agentKeyOrId}` });
50	    return;
51	  }
52	  if (!canUseAgent(user, agentId)) {
53	    sendJson(res, 403, { error: "Forbidden" });
54	    return;
55	  }
56	
57	  // Memory already holds the history, so only the newest message is taken from the body: either a
58	  // new user message, or the assistant message carrying the user's tool-approval decisions.
59	  let last: UIMessage;
60	  try {
61	    const body = JSON.parse(await readBody(req)) as { messages?: unknown; message?: unknown };
62	    const candidate = (Array.isArray(body?.messages) ? body.messages.at(-1) : body?.message) as UIMessage | undefined;
63	    if (!candidate || typeof candidate.id !== "string" || !Array.isArray(candidate.parts)) throw new Error("message required");
64	    if (candidate.role !== "user" && candidate.role !== "assistant") throw new Error("unsupported role");
65	    last = candidate;
66	  } catch (error) {
67	    const tooLarge = error instanceof BodyTooLargeError;
68	    sendJson(res, tooLarge ? 413 : 400, {
69	      error: tooLarge ? "Request body too large" : "Expected JSON body whose last message is a user message or a tool approval",
70	    });
71	    return;
72	  }
73	
74	  let message: UIMessage;
75	  if (last.role === "user") {
76	    // Namespace the id by user: storage upserts by message id, so a client-chosen id must not hit another user's rows.
77	    message = { ...last, id: `${user.id}:${last.id}` };
78	    await dropPendingApprovals(agentId, user);
79	  } else {
80	    // Approval response: only decisions for approvals pending in the caller's own thread are kept.
81	    // It resumes the suspended run; the message itself is not stored.
82	    const thread = await ownThread(agentId, user);
83	    const stored = thread ? (await thread.memory.recall({ ...thread.ids, perPage: false })).messages : [];
84	    const resume = approvalResumeMessage(last, pendingApprovalIds(stored));
85	    if (!resume) {
86	      sendJson(res, 409, { error: "That approval is no longer pending." });
87	      return;
88	    }
89	    message = resume;
90	  }
91	
92	  // Stop generation when the browser disconnects.
93	  const abort = new AbortController();
94	  res.on("close", () => {
95	    if (!res.writableFinished) abort.abort();
96	  });
97	
98	  // Only the message is taken from the client: other AgentExecutionOptions (instructions,
99	  // maxSteps, tools, runId...) must not be client-controlled. Memory thread and resource always
100	  // come from the session, never from the client. With an approval message (last role
101	  // "assistant"), handleChatStream resumes each approved/denied tool call by its run id instead.
102	  const stream = await handleChatStream({
103	    mastra,
104	    agentId,
105	    version: "v7",
106	    params: {
107	      messages: [message],
108	      memory: { thread: chatThreadId(user.id, agentId), resource: user.id },
109	      abortSignal: abort.signal,
110	    },
111	    onError: (error) => {
112	      console.error("Web chat stream failed", { agentId, error });
113	      return "Sorry, something went wrong while generating a reply.";
114	    },
115	  });
116	  const response = createUIMessageStreamResponse({ stream });
117	
118	  res.writeHead(response.status, Object.fromEntries(response.headers));
119	  res.flushHeaders();
120	  if (!response.body) {
121	    res.end();
122	    return;
123	  }
124	  try {
125	    for await (const chunk of response.body) {
126	      if (abort.signal.aborted) break;
127	      res.write(chunk);
128	    }
129	  } finally {
130	    res.end();
131	  }
132	}
133	
134	/** GET/DELETE /api/chat/:agentId/history — read or clear the caller's own chat with one agent. */
135	export async function handleChatHistory(
136	  agentKeyOrId: string,
137	  req: http.IncomingMessage,
138	  res: http.ServerResponse,
139	  user: SessionUser,
140	): Promise<void> {
141	  if (req.method !== "GET" && req.method !== "DELETE") {
142	    res.writeHead(405, { allow: "GET, DELETE" }).end();
143	    return;
144	  }
145	  const agentId = resolveAgentId(agentKeyOrId);
146	  if (!agentId) {
147	    sendJson(res, 404, { error: `Unknown agent: ${agentKeyOrId}` });
148	    return;
149	  }
150	  if (!canUseAgent(user, agentId)) {
151	    sendJson(res, 403, { error: "Forbidden" });
152	    return;
153	  }
154	
155	  const thread = await ownThread(agentId, user);
156	  if (req.method === "DELETE") {
157	    if (thread) await thread.memory.deleteThread(thread.ids.threadId);
158	    res.writeHead(204).end();
159	    return;
160	  }
161	  if (!thread) {
162	    sendJson(res, 200, { messages: [] });
163	    return;
164	  }
165	  const { messages } = await thread.memory.recall({ ...thread.ids, perPage: false });
166	  sendJson(res, 200, { messages: toAISdkMessages(messages, { version: "v7" }) });
167	}
168	
169	/**
170	 * The caller's own saved chat with an agent, or undefined when there is none. The thread id embeds
171	 * the user id and the resource id is checked, so only the caller's own chat is reachable.
172	 */
173	async function ownThread(agentId: string, user: SessionUser) {
174	  const agent = Object.values(mastra.listAgents()).find((a) => a.id === agentId);
175	  const memory = await agent?.getMemory();
176	  const threadId = chatThreadId(user.id, agentId);
177	  const thread = memory ? await memory.getThreadById({ threadId }) : null;
178	  if (!memory || thread?.resourceId !== user.id) return undefined;
179	  return { memory, ids: { threadId, resourceId: user.id } };
180	}
181	
182	/**
183	 * A new user message moves past any approval still awaiting a decision: it is cleared from the
184	 * stored history (so it is no longer offered, and a late decision gets 409) and its suspended run
185	 * is discarded, deleting the same snapshot rows Mastra deletes when an agent run finishes.
186	 */
187	async function dropPendingApprovals(agentId: string, user: SessionUser): Promise<void> {
188	  const thread = await ownThread(agentId, user);
189	  if (!thread) return;
190	  const { messages } = await thread.memory.recall({ ...thread.ids, perPage: false });
191	  const dropped = withoutPendingApprovals(messages);
192	  if (dropped.messages.length === 0) return;
193	  const storage = mastra.getStorage();
194	  await (await storage?.getStore("memory"))?.updateMessages({ messages: dropped.messages });
195	  const workflows = await storage?.getStore("workflows");
196	  for (const runId of dropped.runIds) {
197	    await workflows?.deleteWorkflowRunById({ runId, workflowName: "agentic-loop" });
198	    await workflows?.deleteWorkflowRunById({ runId, workflowName: "executionWorkflow" });
199	  }
200	}
201	
202	export function sendJson(res: http.ServerResponse, status: number, body: unknown): void {
203	  res.writeHead(status, { "content-type": "application/json; charset=utf-8" });
204	  res.end(JSON.stringify(body));
205	}
206	
207	class BodyTooLargeError extends Error {}
208	
209	async function readBody(req: http.IncomingMessage): Promise<string> {
210	  const chunks: Buffer[] = [];
211	  let size = 0;
212	  for await (const chunk of req) {
213	    size += (chunk as Buffer).length;
214	    if (size > MAX_BODY_BYTES) throw new BodyTooLargeError();
215	    chunks.push(chunk as Buffer);
216	  }
217	  return Buffer.concat(chunks).toString("utf8");
