25	    }
26	    if (isReasoningUIPart(part)) {
27	      if (part.text.trim()) segments.push({ kind: "reasoning", text: part.text, key });
28	      return;
29	    }
30	    if (isToolUIPart(part) && part.state === "approval-requested") {
