// Temporary verification: supervisor -> sub-agent approval through the REAL chat-api handleChat path.
import { mkdtempSync, rmSync } from "node:fs";
import http from "node:http";
import { join } from "node:path";
import { MockLanguageModelV3 } from "ai/test";
import { readUIMessageStream, simulateReadableStream, type UIMessage, type UIMessageChunk } from "ai";

const SCRATCH = "/private/tmp/claude-501/-Users-apple-Open-nlhack/e59c2249-0b87-4a1c-ba98-59e4bbeb45ac/scratchpad";
const dir = mkdtempSync(join(SCRATCH, "deleg-"));
process.env.DATA_DIR = dir;
delete process.env.NEATLOGS_API_KEY;
delete process.env.GITHUB_PAT;

const REPO = "/Users/apple/Open/nlhack";
const { mastra } = await import(`${REPO}/src/mastra/index.ts`);
const { handleChat, handleChatHistory } = await import(`${REPO}/src/chat-api.ts`);
const { githubAgent } = await import(`${REPO}/src/mastra/agents/github.ts`);
const { assistant } = await import(`${REPO}/src/mastra/agents/assistant.ts`);
const { messageSegments } = await import(`${REPO}/web/src/lib/message-parts.ts`);
const { createTool } = await import("@mastra/core/tools");
const { z } = await import("zod");

const results: [string, boolean, unknown?][] = [];
const check = (name: string, ok: boolean, info?: unknown) => {
  results.push([name, ok, info]);
  console.log(`${ok ? "PASS" : "FAIL"} ${name}${ok || info === undefined ? "" : ` :: ${JSON.stringify(info)}`}`);
};

// ---- mocks ----------------------------------------------------------------------------------
const usage = {
  inputTokens: { total: 1, noCache: 1, cacheRead: undefined, cacheWrite: undefined },
  outputTokens: { total: 1, text: 1, reasoning: undefined },
};
function streamOf(chunks: any[]) {
  return { stream: simulateReadableStream({ chunks: [{ type: "stream-start", warnings: [] }, ...chunks] }) };
}
const textReply = (text: string) =>
  streamOf([
    { type: "text-start", id: "t" },
    { type: "text-delta", id: "t", delta: text },
    { type: "text-end", id: "t" },
    { type: "finish", finishReason: { unified: "stop", raw: undefined }, usage },
  ]);
const toolCall = (toolName: string, input: unknown) =>
  streamOf([
    { type: "tool-call", toolCallId: `call-${toolName}-${Math.random().toString(36).slice(2, 8)}`, toolName, input: JSON.stringify(input) },
    { type: "finish", finishReason: { unified: "tool-calls", raw: undefined }, usage },
  ]);
const lastRole = (prompt: any[]) => prompt.at(-1)?.role;
const lastUserText = (prompt: any[]) =>
  JSON.stringify([...prompt].reverse().find((m: any) => m.role === "user")?.content ?? "");

const ISSUE_ARGS = { owner: "acme", repo: "app", title: "Bug from delegation" };
let toolRuns = 0;

assistant.__updateModel({
  model: new MockLanguageModelV3({
    doStream: async ({ prompt }: any) => {
      if (lastRole(prompt) === "tool") return textReply("Assistant: the specialist finished.");
      if (lastUserText(prompt).includes("never mind")) return textReply("Assistant: OK, dropped.");
      return toolCall("agent-githubAgent", { prompt: "Create an issue in acme/app titled 'Bug from delegation'." });
    },
  }),
});
githubAgent.__updateModel({
  model: new MockLanguageModelV3({
    doStream: async ({ prompt }: any) =>
      lastRole(prompt) === "tool" ? textReply("GitHub: done with the issue request.") : toolCall("github_create_issue", ISSUE_ARGS),
  }),
});
githubAgent.__setTools({
  github_create_issue: createTool({
    id: "github_create_issue",
    description: "Create an issue",
    inputSchema: z.object({ owner: z.string(), repo: z.string(), title: z.string() }),
    requireApproval: true,
    execute: async () => {
      toolRuns++;
      return { url: "https://github.com/acme/app/issues/1" };
    },
  }),
});

// ---- real handleChat behind a local HTTP server --------------------------------------------
const user = { id: "u1", name: "U", username: "u", role: "member" as const };
const server = http.createServer((req, res) => {
  const url = new URL(req.url!, "http://x");
  const m = url.pathname.match(/^\/api\/chat\/([^/]+)(\/history)?$/);
  if (!m) return void res.writeHead(404).end();
  void (m[2] ? handleChatHistory(m[1], req, res, user as any) : handleChat(m[1], req, res, user as any));
});
await new Promise<void>((r) => server.listen(0, "127.0.0.1", r));
const base = `http://127.0.0.1:${(server.address() as any).port}`;

async function post(message: UIMessage) {
  const res = await fetch(`${base}/api/chat/assistant`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ messages: [message] }),
  });
  if (!res.ok) return { status: res.status, chunks: [] as any[], message: undefined as UIMessage | undefined };
  const text = await res.text();
  const chunks = text
    .split("\n")
    .filter((l) => l.startsWith("data: ") && l !== "data: [DONE]")
    .map((l) => JSON.parse(l.slice(6)));
  // Build the live UIMessage the browser would hold (as useChat does).
  let message: UIMessage | undefined;
  for await (const m of readUIMessageStream({
    stream: new ReadableStream<UIMessageChunk>({
      start(c) {
        for (const ch of chunks) c.enqueue(ch);
        c.close();
      },
    }),
  })) message = m;
  return { status: res.status, chunks, message };
}
const userMsg = (text: string): UIMessage => ({ id: `m-${Math.random()}`, role: "user", parts: [{ type: "text", text }] });
async function history(): Promise<UIMessage[]> {
  return (await (await fetch(`${base}/api/chat/assistant/history`)).json()).messages;
}
const workflows = await mastra.getStorage()!.getStore("workflows");
async function hasSnapshot(runId: string) {
  for (const workflowName of ["agentic-loop", "executionWorkflow"]) {
    if (await workflows!.loadWorkflowSnapshot({ workflowName, runId })) return true;
  }
  return false;
}
async function pendingEntries(): Promise<any[]> {
  const memory = await assistant.getMemory();
  const { messages } = await memory!.recall({ threadId: "u1:assistant", resourceId: "u1", perPage: false });
  return messages.flatMap((m: any) => Object.values(m.content?.metadata?.pendingToolApprovals ?? {}));
}
const agentNames = { githubAgent: "GitHub Agent", neatlogsAgent: "Neatlogs Agent" };

function approvalFromStream(r: Awaited<ReturnType<typeof post>>) {
  const req = r.chunks.find((c) => c.type === "tool-approval-request");
  const data = r.chunks.find((c) => c.type === "data-tool-call-approval");
  return { req, data };
}
function respond(message: UIMessage, approvalId: string, approved: boolean): UIMessage {
  return {
    ...message,
    parts: message.parts.map((p: any) =>
      p.approval?.id === approvalId ? { ...p, state: "approval-responded", approval: { id: approvalId, approved } } : p,
    ),
  };
}

// ---- 1. approval request surfaces + approve runs the sub tool once ---------------------------
let r = await post(userMsg("Please open an issue in acme/app"));
let { req, data } = approvalFromStream(r);
check("1a approval request emitted on agent-githubAgent", !!req && r.chunks.some((c) => c.type === "tool-input-available" && c.toolName === "agent-githubAgent" && c.toolCallId === req.toolCallId), r.chunks.map((c) => c.type));
check("1b data-tool-call-approval carries nested tool + args", data?.data?.toolName === "github_create_issue" && JSON.stringify(data?.data?.args) === JSON.stringify(ISSUE_ARGS), data);

// web: live-stream segments
let segs = messageSegments(r.message!, agentNames);
let appr = segs.filter((s: any) => s.kind === "approval");
check("1c live segments: one approval with nested tool/args/agent", appr.length === 1 && appr[0].toolName === "github_create_issue" && JSON.stringify(appr[0].input) === JSON.stringify(ISSUE_ARGS) && appr[0].agent === "GitHub Agent" && appr[0].label === "Github create issue" && appr[0].approvalId === req.approvalId, segs);
check("1d live segments: data part renders no extra step", !segs.some((s: any) => s.kind === "tools" && s.steps.some((st: any) => /approval/i.test(st.label))), segs);
console.log("   live segments:", JSON.stringify(segs.map((s: any) => ({ kind: s.kind, ...(s.kind === "approval" ? { toolName: s.toolName, label: s.label, agent: s.agent } : s.kind === "tools" ? { steps: s.steps.map((x: any) => x.label) } : {}) }))));

// web: history-loaded segments
let hist = await history();
let lastAssistant = hist.filter((m) => m.role === "assistant").at(-1)!;
console.log("   history parts:", JSON.stringify(lastAssistant.parts.map((p: any) => ({ type: p.type, state: p.state, toolCallId: p.toolCallId ?? p.data?.toolCallId, toolName: p.toolName ?? p.data?.toolName }))));
segs = messageSegments(lastAssistant, agentNames);
appr = segs.filter((s: any) => s.kind === "approval");
check("1e history segments: one approval with nested tool/args/agent", appr.length === 1 && appr[0].toolName === "github_create_issue" && JSON.stringify(appr[0].input) === JSON.stringify(ISSUE_ARGS) && appr[0].agent === "GitHub Agent" && appr[0].approvalId === req.approvalId, segs);

let pend = await pendingEntries();
check("1f stored pending entry has delegatedRunId + nested tool", pend.length === 1 && typeof pend[0].delegatedRunId === "string" && pend[0].toolName === "github_create_issue" && pend[0].parentToolName === "agent-githubAgent", pend);
const firstSub = pend[0]?.delegatedRunId as string;
const firstSup = pend[0]?.runId as string;
check("1g supervisor + delegated snapshots exist while pending", (await hasSnapshot(firstSup)) && (await hasSnapshot(firstSub)), { firstSup, firstSub });

r = await post(respond(r.message!, req.approvalId, true));
check("1h approve: status 200 and sub tool ran exactly once", r.status === 200 && toolRuns === 1, { status: r.status, toolRuns });
const texts = r.chunks.filter((c) => c.type === "text-delta").map((c) => c.delta).join("");
check("1i approve: assistant reply continued", texts.includes("Assistant: the specialist finished."), texts);
check("1j approve: nothing pending afterwards", (await pendingEntries()).length === 0);
// A replayed approval is refused.
r = await post(respond((await history()).filter((m) => m.role === "assistant").at(-1)!, req.approvalId, true));
check("1k replayed approval -> 409, tool not rerun", r.status === 409 && toolRuns === 1, { status: r.status, toolRuns });

// ---- 2. deny runs the sub tool 0 times ------------------------------------------------------
r = await post(userMsg("Open another issue in acme/app"));
({ req } = approvalFromStream(r));
const runsBefore = toolRuns;
r = await post(respond(r.message!, req.approvalId, false));
check("2a deny: status 200, sub tool ran 0 times", r.status === 200 && toolRuns === runsBefore, { status: r.status, toolRuns, runsBefore });
check("2b deny: nothing pending afterwards", (await pendingEntries()).length === 0);

// ---- 3. new user message while pending drops it and deletes the delegated snapshot ----------
r = await post(userMsg("Open a third issue in acme/app"));
({ req } = approvalFromStream(r));
const pendingMsg = r.message!;
pend = await pendingEntries();
const sup3 = pend[0]?.runId as string;
const sub3 = pend[0]?.delegatedRunId as string;
check("3a pending with snapshots for supervisor and sub-agent", pend.length === 1 && (await hasSnapshot(sup3)) && (await hasSnapshot(sub3)), { sup3, sub3 });
r = await post(userMsg("never mind"));
check("3b new message ok", r.status === 200);
check("3c pending approval cleared from history", (await pendingEntries()).length === 0);
check("3d supervisor snapshot deleted", !(await hasSnapshot(sup3)));
check("3e delegated sub-agent snapshot deleted", !(await hasSnapshot(sub3)));
const runs3 = toolRuns;
r = await post(respond(pendingMsg, req.approvalId, true));
check("3f late approval -> 409, tool not run", r.status === 409 && toolRuns === runs3, { status: r.status, toolRuns });

// ---- 4. fallback: non-delegated approval keeps current behaviour ---------------------------
const plain: UIMessage = {
  id: "x",
  role: "assistant",
  parts: [
    { type: "tool-github_create_issue", toolCallId: "c1", state: "approval-requested", input: ISSUE_ARGS, approval: { id: "r::c1" } } as any,
    { type: "data-tool-call-approval", id: "c1", data: { toolCallId: "c1", toolName: "github_create_issue", args: ISSUE_ARGS } } as any,
  ],
};
segs = messageSegments(plain, agentNames);
check("4a direct approval: no agent, own tool name", segs.length === 1 && segs[0].kind === "approval" && segs[0].agent === undefined && segs[0].toolName === "github_create_issue", segs);
const noData: UIMessage = { ...plain, parts: [{ type: "tool-agent-githubAgent", toolCallId: "c2", state: "approval-requested", input: { prompt: "p" }, approval: { id: "r::c2" } } as any] };
segs = messageSegments(noData, agentNames);
check("4b delegated without data part: falls back to delegation tool", segs.length === 1 && segs[0].toolName === "agent-githubAgent" && segs[0].agent === undefined && segs[0].label === "Delegated to GitHub Agent", segs);

server.close();
const failed = results.filter(([, ok]) => !ok).length;
console.log(`\n${results.length - failed}/${results.length} checks passed`);
rmSync(dir, { recursive: true, force: true });
process.exit(failed ? 1 : 0);

